using Xunit;

namespace JoshOlson.Database.Locks;

public class SchemaLockWriterTests {
  [Fact]
  public void Write_ProducesTheCanonicalText() {
    var expected = $$"""
      # Generated by the seed tool. Never edit by hand (ADR 0034, lock file and branch-safe migration).
      version: 3
      migrations:
        - version: 1
          file: V001__foo.sql
          checksum: {{SchemaLockSample.Aaa}}
        - version: 3
          file: V003__bar.sql
          checksum: {{SchemaLockSample.Bbb}}
          accepted_checksums:
            - {{SchemaLockSample.Ccc}}
      tables:
        foo.bar:
          - { name: bar_id, type: bigint, primary_key: 1 }
          - { name: name, type: text }
          - { name: note, type: text, nullable: true }
          - { name: created_utc, type: timestamptz, policy: relative }
          - { name: published_utc, type: timestamptz, nullable: true, policy: absolute }
        foo.link:
          - { name: bar_id, type: bigint, primary_key: 1 }
          - { name: tag_id, type: smallint, primary_key: 2 }
          - { name: flags, type: "smallint[]", nullable: true }

      """;

    Assert.Equal(expected, SchemaLockWriter.Write(SchemaLockSample.Create()));
  }

  [Fact]
  public void Write_UsesLfAndEndsWithOneNewline() {
    var text = SchemaLockWriter.Write(SchemaLockSample.Create());

    Assert.DoesNotContain('\r', text);
    Assert.EndsWith("\n", text, StringComparison.Ordinal);
    Assert.DoesNotContain("\n\n", text, StringComparison.Ordinal);
  }

  [Fact]
  public void Write_EmptyLock_WritesEmptyCollections() {
    var text = SchemaLockWriter.Write(new() {
      Version = 0,
      Migrations = [],
      Tables = [],
    });

    Assert.Contains("migrations: []\n", text, StringComparison.Ordinal);
    Assert.Contains("tables: {}\n", text, StringComparison.Ordinal);
  }

  [Fact]
  public void Write_NamesThatCannotBePlain_AreQuoted() {
    var schemaLock = SchemaLockSample.Create() with {
      Tables = [
        new() {
          Name = "foo.bar",
          Columns = [
            SchemaLockSample.Column("my col", "text"),
            SchemaLockSample.Column("-dash", "text"),
          ],
        },
      ],
    };

    var text = SchemaLockWriter.Write(schemaLock);

    Assert.Contains("{ name: \"my col\", type: text }", text, StringComparison.Ordinal);
    Assert.Contains("{ name: \"-dash\", type: text }", text, StringComparison.Ordinal);
  }

  [Fact]
  public void Write_SameLockTwice_GivesIdenticalText()
    => Assert.Equal(SchemaLockWriter.Write(SchemaLockSample.Create()), SchemaLockWriter.Write(SchemaLockSample.Create()));
}
